  _ = `Končí dne: %1$s`,
  _ = `Nejsou dostupné informace o žádné předchozí slevě`,
  _ = `Aktuální cena: %1$s`,
  _ = `Aplikace není dostupná v obchodu služby Steam`,
  _ = `Balíček není dostupný v obchodu služby Steam`,
  _ = `Balík není dostupný v obchodu služby Steam`,
  _ = `Upozornění: V tuto chvíli máte aktivní %1$s% slevu`,
  _ = `Vytvořit nabídku dne`,
  _ = `Délka (%1$s–%2$s dnů)`,
  _ = `Délka`,
  _ = `Pro tuto hru je už naplánována další sleva začínající o %1$s dní později. Z toho důvodu bude tato sleva omezena na nejvýše %2$s dnů.`,
  _ = `Od %3$s je plánován %2$s. Pokud se tohoto výprodeje chcete zúčastnit, délka slevy pro nabídku dne by měla být nejvýše %1$s den.`,
  _ = `Od %3$s je plánován %2$s. Pokud se tohoto výprodeje chcete zúčastnit, délka slevy pro nabídku dne by měla být nejvýše %1$s dny.`,
  _ = `Otevřít dokumentaci`,
  _ = `Vyberte balíky pro zlevnění (nejméně jeden):`,
  _ = `Aktivní prodleva skončí %1$s`,
  _ = `Vybraná položka:`,
  _ = `Tato položka se objeví ve slotu pro nabídku dne doplněná svojí cenou, slevou a obrázkem pro výběr. Ve většině případů doporučujeme ponechat výchozí možnost, tedy samotnou hru.`,
  _ = `Hra: %1$s`,
  _ = `Balík: %1$s`,
  _ = `Balíček: %1$s`,
  _ = `Odkaz (pokud se nejedná o stránku hry/balíčku v obchodě)`,
  _ = `Zadejte URL adresu stránky výprodeje nebo stránky v jiném obchodě`,
  _ = `Nepodařilo se vytvořit nabídku dne. Zkuste to později znovu.`,
  _ = `Opravdu chcete pokračovat? Přijdete tak o veškeré neuložené změny.`,
  _ = `Datum není dostupné`,
  _ = `Pro tento den nejsou dostupné sloty nabídky dne.`,
  _ = `Chyba: Neplatné ID partnera`,
  _ = `Chyba: Neplatné ID pozvánky`,
  _ = `Tato pozvánka do nabídky dne byla už přijata`,
  _ = `Pozvánka vypršela %1$s`,
  _ = `Zpět na %1$s`,
  _ = `Nemáte k dispozici žádné pozvánky do nabídky dne. Pro více informací a požadavky účasti si přečtěte <1>dokumentaci</1>.`,
  _ = `Nemáte žádné naplánované nabídky dne`,
  _ = `Pozvánky`,
  _ = `Nedokončeno`,
  _ = `Tyto nabídky neproběhnou, dokud nebudou dokončeny všechny kroky`,
  _ = `Naplánované nabídky dne`,
  _ = `Historie (%1$s)`,
  _ = `hledat nabídky dne dle názvu nebo ID`,
  _ = `Přihlášky do nabídky dne`,
  _ = `Vyberte datum v rámci následujících %1$s měsíců, kdy se má Vaše hra zúčastnit nabídky dne.`,
  _ = `Zahájení slevy budete moci nastavit na stejné datum, ale dle potřeby i na dřívější datum.`,
  _ = `Přihlášku musíte zadat nejpozději do %1$s.`,
  _ = `Tato pozvánka vyprší dne %1$s.`,
  _ = `Vytvořit nabídku dne`,
  _ = `Vytvořit nabídku dne – %1$s`,
  _ = `Chyba: Pro tuto nabídku dne nemáte žádnou vhodnou hru.`,
  _ = `Vyberte aplikaci`,
  _ = `Do nabídky dne bylo pozváno více z Vašich aplikací. Vyberte tedy tu, kterou chcete použít pro toto datum.`,
  _ = `Chybí obrázek záhlaví`,
  _ = `Chybí obrázek záhlaví balíčku`,
  _ = `Chybí obrázek záhlaví`,
  _ = `Zadejte požadovanou slevu`,
  _ = `Pozvánka přijata`,
  _ = `Vystavení: %1$s`,
  _ = `Sleva: %1$s–%2$s`,
  _ = `Chybějící sleva`,
  _ = `Vyberte datum`,
  _ = `Volná data: %1$s`,
  _ = `Vyberte datum a přihlaste svoji hru do %1$s`,
  _ = `Zadat slevy`,
  _ = `Upravit slevy`,
  _ = `Nejprve musíte vybrat datum`,
  _ = `Tato nabídka dne je AKTIVNÍ!`,
  _ = `Tato nabídka dne byla dokončena %1$s`,
  _ = `Tato nabídka dne se nezobrazila, protože v daném časovém rozmezí neexistovala pro hru žádná sleva.`,
  _ = `Tato nabídka dne byla zrušena`,
  _ = `Tato pozvánka byla zrušena`,
  _ = `Jak fungují pozvánky?`,
  _ = `Pokud Vaši hru pozveme k účasti na nabídce dne, obdržíte zprávu e-mailem a hra bude uvedena výše. Proces poté pokračuje následovně:`,
  _ = `Vyberte z následujících 6 měsíců volné datum, které Vám vyhovuje.`,
  _ = `Prominentní viditelnost na hlavní stránce obchodu a v centrech vhodných značek trvá 24 hodin, zatímco samotná sleva platí na základě Vašeho nastavení od 7 do 14 dnů. K zahájení slevy dojde v 19.00 (10.00 pacifického času) vybraného data.`,
  _ = `Až si vyberete volné datum, budete vyzváni k zadání výše slevy v procentech a výběru balíků, které mají být zahrnuty.`,
  _ = `Procentuální sleva by měla být alespoň stejně vysoká jako největší sleva, kterou jste kdy nabízeli, ideálně ještě vyšší.`,
  _ = `Pokud nejste v tuto chvíli připraveni naplánovat nabídku dne, nevadí – pozvánka zůstane dostupná na panelu nabídek dne. Akorát ji nezapomeňte využít, než vyprší.`,
  _ = `Pokud potřebujete změnit datum, zrušit nabídku nebo máte nějaký dotaz – %1$s`,
  _ = `Kontaktujte nás`,
  _ = `Tipy pro nabídku dne`,
  _ = `Vývojářům se často osvědčilo spojit zvýšenou viditelnost a slevu s dalšími plánovanými akcemi, mezi něž se řadí například aktualizace hry, přenosy nebo komunitní události.`,
  _ = `Pokud máte pro měsíc s nabídkou dne naplánovanou jinou slevu, zkuste pro obě slevy zachovat stejnou procentuální výši. Nabídku dne se totiž většinou snažíme koncipovat tak, aby byla její sleva stejná nebo vyšší než předchozí sleva (či slevy) na danou hru.`,
  _ = `Pro více informací navštivte <1>dokumentaci</1>.`,
  _ = `Viditelnost`,
  _ = `Nabídka dne použije pro Vaši hru její obrázek pro výběr v hlavičce a vystaví ji na domovské stránce obchodu služby Steam.`,
