  _ = `Pokud byste pro tuto nabídku dne raději vytvořili novou slevu, smažte na %1$s stávající slevu a do pole „Sleva v procentech“ zadejte číslo 0, nebo pro nabídku dne vyberte jiné datum.`,
  _ = `stránce se správou slev`,
