  _ = `Vyberte z následujících %1$s měsíců volné datum, které Vám vyhovuje.`,
  _ = `Prominentní viditelnost na hlavní stránce obchodu a v centrech vhodných značek trvá %1$s dny, zatímco samotná sleva platí na základě Vašeho nastavení od 7 do 14 dnů. K zahájení slevy dojde v 19.00 (10.00 pacifického času) vybraného data.`,
  _ = `Až si vyberete volné datum, budete vyzváni k zadání výše slevy v procentech a výběru balíků, které mají být zahrnuty.`,
  _ = `Procentuální sleva by měla být alespoň stejně vysoká jako největší sleva, kterou jste kdy nabízeli, ideálně ještě vyšší.`,
  _ = `Pokud nejste v tuto chvíli připraveni naplánovat slevové šílenství, nevadí – pozvánka zůstane dostupná na panelu. Akorát ji nezapomeňte využít, než vyprší.`,
  _ = `Pokud nejste v tuto chvíli připraveni naplánovat víkendovou akci, nevadí – pozvánka zůstane dostupná na panelu. Akorát ji nezapomeňte využít, než vyprší.`,
  _ = `Tipy a triky`,
  _ = `Pokud máte pro měsíc se slevovým šílenstvím naplánovanou jinou slevu, zkuste pro obě slevy zachovat stejnou procentuální výši. Slevové šílenství se totiž většinou snažíme koncipovat tak, aby byla jeho sleva stejná nebo vyšší než předchozí sleva (či slevy) na danou hru.`,
  _ = `Pokud máte pro měsíc s víkendovou akcí naplánovanou jinou slevu, zkuste pro obě slevy zachovat stejnou procentuální výši. Víkendovou akci se totiž většinou snažíme koncipovat tak, aby byla její sleva stejná nebo vyšší než předchozí sleva (či slevy) na danou hru.`,
