  _ = `Aby se Vaše demoverze mohla zúčastnit festivalu Steam Next, musí projít kontrolou buildu, v rámci které ověříme, jestli funguje a nabízí slibované funkce. Tato kontrola nesupluje kompletní QA, takže dál testujte i Vy sami.`,
