  _ = `Žádost o použití upoutávky`,
  _ = `Může služba Steam použít Vaši upoutávku k propagaci události „%1$s“?`,
  _ = `Pokud ano, nejpozději do %1$s potvrďte přihlášku a použití odsouhlaste. Aby se Vaše hra mohla zúčastnit, musíte pro ni také naplánovat slevu. Pro více informací klikněte na tlačítko níže.`,
  _ = `Souhlaste s použitím upoutávky do:`,
  _ = `Může služba Steam použít Vaši upoutávku k propagaci události „%1$s“?`,
  _ = `Pokud ano, nejpozději do %1$s potvrďte přihlášku a použití odsouhlaste. Pro více informací klikněte na tlačítko níže.`,
  _ = `Souhlaste s použitím upoutávky do:`,
