  _ = `Aby bylo zajištěno, že splňují požadavky na kvalitu, marketingové zprávy velké aktualizace vyžadují kontrolu společností Valve skrze žádost na podporu. Žádost lze vytvořit v záložce „Zveřejnit“ při editování související události.`,
