  _ = `Stránka výprodeje (koncept)`,
  _ = `Tato událost prozatím není viditelná, ale Vy máte výjimku, protože na stránce je zahrnuta Vaše hra. Pokud je to pro Vás novinka, obraťte se na pořadatele události.`,
  _ = `Tady můžete vidět, jak si na události vedly Vaše hry!`,
