  _ = `Zúčastnili jste se s jednou další hrou, ale pro zobrazení detailních statistik byste pro ni museli disponovat oprávněním „%2$s“.`,
  _ = `Zúčastnili jste se s %1$s dalšími hrami, ale pro zobrazení detailních statistik byste pro ně museli disponovat oprávněním „%2$s“.`,
  _ = `Otevřít celý souhrn`,
