  _ = `15. listopadu skryjeme v Německu z prodeje aplikace bez ratingu`,
  _ = `Jedna z Vašich aplikací postrádá rating a služba Steam bude nucena ji počínaje 15. listopadem 2024 skrýt v Německu z obchodu. Abyste zajistili, že Vaše aplikace zůstane dostupná pro tamní zákazníky, vyplňte a zveřejněte zabudovaný dotazník ohledně obsahu.`,
  _ = `Několik z Vašich aplikací postrádá rating a služba Steam bude nucena je počínaje 15. listopadem 2024 skrýt v Německu z obchodu. Abyste zajistili, že Vaše aplikace zůstanou dostupné pro tamní zákazníky, vyplňte a zveřejněte zabudovaný dotazník ohledně obsahu.`,
