  _ = `Komunikace`,
  _ = `Přidělte sobě nebo kolegům oprávnění pro příjem důležitých e-mailových zpráv od systému Steamworks.`,
  _ = `Nikdo z Vaší organizace v tuto chvíli nepřijímá komunikaci od systému Steamworks. Přidělte tedy jednomu nebo více uživatelům s platnou e-mailovou adresou oprávnění „Komunikace od systému Steamworks“, díky němuž budou dostávat e-maily ohledně nadcházejících výprodejů, cílených událostí a nových funkcí služby Steam.`,
  _ = `Spravovat oprávnění`,
