  _ = `Byla vyžádána poštovní adresa`,
  _ = `Společnost Valve by Vám chtěla něco poslat. Nejpozději do %1$s nám tedy poskytněte svoji poštovní adresu, nebo odmítněte příslušnou nabídku.`,
  _ = `Společnost Valve by Vám chtěla něco poslat. Příslušná nabídka vypršela %1$s, ale stále nám můžete poskytnout svoji poštovní adresu, nebo nabídku odmítnout.`,
  _ = `Společnost Valve by Vám chtěla něco poslat. Poskytněte nám tedy svoji poštovní adresu, nebo odmítněte příslušnou nabídku.`,
  _ = `Poskytnout adresu`,
  _ = `Poštovní adresa`,
