  _ = `Fyzická poštovní adresa se může lišit od adresy, kterou jste zadali při registraci do systému Steamworks. Pokud je Váš účet systému Steamworks používán na více fyzických adresách, můžete je odděleně zadat všechny.`,
  _ = `Přidat novou adresu`,
