  _ = `Vaše platební údaje jsou už déle než 12 měsíců neaktivní a vyprší dne %1$s.<br><br>Pokud do data vypršení platnosti neprovedete žádnou akci, tyto platební údaje budou zrušeny a nebudeme schopni Vám vyplácet platby.`,
