  _ = `Build Vaší demoverze musí být zkontrolován! Nejpozději k tomuto datu ho tedy odešlete, abychom kontrolu stihli dokončit před zahájením festivalu Steam Next. <1>Více informací o procesu kontroly.</1>`,
