  _ = `Ochrana proti cheatování`,
  _ = `Pokud Vaše hra instaluje na klientských zařízeních ochranu proti cheatování pracující na úrovni jádra operačního systému, musíte o tom zde informovat uživatele. Pokud máte svoji vlastní ochranu, nebo Vaše ochrana není uvedena v seznamu níže, vyberte možnost „Jiná“ a zadejte příslušné informace.`,
  _ = `Pokud Vaše hra zahrnuje ochranu proti cheatování, která nemění soubory na úrovni jádra (nezávisle na tom, jestli je instalována na klientská zařízení, nebo běží na serveru), je vyplnění pole dobrovolné, ale obecně si myslíme, že z transparentnosti v tomto ohledu mohou profitovat všechny tituly.`,
  _ = `Ochrana proti cheatování:`,
  _ = `Integrace na úrovni jádra`,
  _ = `Tato ochrana proti cheatování zahrnuje instalaci nebo modifikaci souborů na úrovni jádra OS.`,
  _ = `Tato ochrana proti cheatování nemění soubory na úrovni jádra OS.`,
  _ = `Vyberte, pokud Vaše ochrana proti cheatování instaluje soubory na úrovni jádra OS (nezávisle na herním módu).`,
  _ = `Kompletní odinstalace`,
  _ = `Tuto možnost vyberte pouze v případě, že po odinstalování Vaší hry dojde také k odstranění všech souborů souvisejících s ochranou proti cheatování (nainstalovaných s Vaší hrou).`,
  _ = `Vyžadovaná ochrana bootování`,
  _ = `Pokud Vaše hra pro libovolný herní mód vyžaduje funkci Secure Boot (zabezpečené spouštění), čip TPM nebo jinou ochranu související s bootováním, vyberte požadovanou kombinaci.`,
  _ = `Žádná`,
