  _ = `Unreal Engine obvykle vyžaduje program Visual C++. Některé hry na tomto enginu mohou vyžadovat také DirectX.`,
  _ = `Seskupit edice`,
  _ = `Vysvětlit rozdíly mezi edicemi`,
  _ = `Tento nástroj Vám umožňuje poskytnout obrázek, který popisuje rozdíly mezi edicemi Vaší hry (např. Zlatá edice, Deluxe edice, edice Hra roku apod.). Edice budou na stránce v obchodu seřazeny od nejlevnější po nejdražší, přičemž nad nimi bude jako první možnost zakoupení základní verze hry. Pro více informací navštivte <1>dokumentaci</1>.`,
  _ = `Seskupte více edic své hry (Zlatá edice, Deluxe edice apod.) a volitelně přidejte obrázek s jejich porovnáním.`,
  _ = `(balíky vybrané jako edice: %1$s)`,
