  _ = `Nahrajte obrázek s rozměry %1$s×%2$s pixelů porovnávající vybrané edice. Tento obrázek se zobrazí v dialogovém okně, když zákazník na stránce Vaší hry v obchodu klikne na možnost „Porovnat edice“. Pomocí rozbalovací nabídky jazyků nahrajte lokalizované verze obrázku.`,
  _ = `Aby se uložené změny zobrazily zákazníkům, musíte opětovně <1>zveřejnit</1> stránku hry v obchodu.`,
