  _ = `Pravidla grafických prvků`,
  _ = `Než budete pokračovat, potvrďte prosím, že se Vaše obrázky řídí požadovanými standardy. Pokud obrázky odešlete ke kontrole a nesplní naše požadavky, kontrolou neprojdou a budete je muset upravit. Pro více informací navštivte stránku dokumentace <1>Pravidla grafických prvků</1>.`,
  _ = `Potvrdit a nahrát`,
