  _ = `(obrázky výběrů aplikací zahrnutých v tomto balíku můžete upravit níže na stránce „Úpravy balíku v obchodu“)`,
  _ = `Umožňuje přidat do možnosti nákupu balíku v obchodu také obrázky výběrů zahrnutých aplikací (podobně jako se zobrazuje obsah balíčků). Jako první bude uveden obrázek základní aplikace a další obrázky budou řazeny sestupně od nejdražší po nejlevnější aplikaci.`,
  _ = `Vynechat název hry z názvů položek obsažených v balíku`,
  _ = `Pro snížení opakování a zlepšení čitelnosti je možné z názvů položek (např. DLC a soundtracků) při zobrazení v možnosti nákupu balíku vynechat název základní hry a veškeré mezery a spojovací znaky jako dvojtečky a pomlčky. Nic jiného vynecháno není. Položka „Half-Life 2: Episode One“ by se tak zobrazila pouze jako „Episode One“.`,
