  _ = `Zrušit`,
  _ = `Vybraná událost spojená s velkou aktualizací`,
  _ = `Vlastníci hry budou přesměrováni na událost v knihovně. Událost musí být přiřazená k základní hře.`,
  _ = `[Naplánováno na %1$s] Název události: %2$s`,
