  _ = `[Zahájeno %1$s] Název události: %2$s`,
  _ = `Nebyla nalezena žádná vhodná událost. Je vyžadována událost zveřejněná v rámci posledního měsíce nebo alespoň koncept. <1>Otevřít panel správce</1>`,
  _ = `Vaše umístění loga bylo uloženo. Tyto změny můžete zveřejnit ze správy stránky v obchodě.`,
  _ = `Správa slev`,
  _ = `Data konání výprodejů se mohou změnit. Při veřejném oznamování dat tedy buďte opatrní, obzvlášť co se týče událostí naplánovaných do vzdálené budoucnosti.`,
  _ = `Poznámky`,
  _ = `Připomínka: Slevu libovolného typu nelze nahrát do 30 dnů od prvotního vydání hry za plnou cenu nebo navýšení ceny hry v libovolné měně. Podrobnosti naleznete v %1$s.`,
  _ = `dokumentaci`,
  _ = `Pokud není určeno jinak, slevy vždy začínají a končí v 10.00 pacifického času.`,
  _ = `Vlastní sleva`,
