  _ = `Importovat/exportovat slevy`,
  _ = `Nástroje`,
  _ = `Importovat/exportovat CSV...`,
  _ = `Slevy svých balíků můžete spravovat také prostřednictvím souboru formátu CSV. To se hodí, když potřebujete aktualizovat velké množství slev najednou nebo ověřit konzistentnost slev napříč rozsáhlým katalogem her.`,
  _ = `Stáhněte si kompletní tabulku slev ve formátu CSV. Tato tabulka bude zahrnovat také nevyřízené změny, které ještě nebyly uloženy.`,
  _ = `Stáhnout vše`,
