  _ = `Stáhnout viditelné`,
  _ = `Touto možností stáhnete slevy všech viditelných balíků kromě těch skrytých filtrem nebo sbalením řádek.`,
  _ = `Nahrajte soubor formátu CSV s aktualizovanou tabulkou slev. Veškeré záznamy, které nebudou odpovídat stávajícím slevám, budou zadány jako nevyřízené změny. Před zveřejněním Vám také bude umožněna kontrola.`,
  _ = `Nahrát nové slevy`,
