  _ = `Veškeré možné slevy tohoto balíku na následujících šest měsíců byly zarezervovány.`,
  _ = `Sleva bude automaticky zahájena a ukončena v určená data, takže ji můžete naplánovat v předstihu. Jakmile je však sleva zahájena, nelze ji už dále upravit.`,
  _ = `Tento balík může být zlevněn maximálně o %1$s %.`,
