  _ = `Přihlásit se`,
  _ = `Kliknutím níže projevíte svůj zájem o účast na této události a získáte možnost zadat pro ni slevy. My Vám pak také budeme moci posílat důležité informace týkající se této události. Přihlášku můžete kdykoli zrušit.`,
