  _ = `Není možné nastavit slevu nižší než 10 %.`,
  _ = `Pro některé balíky musíte nastavit nižší slevu, jelikož cena se slevou nemůže klesnout pod 0,49 USD nebo ekvivalentní v dané měně či regionu.`,
  _ = `Pro tento balík nemůžete nastavit slevu vyšší než %1$s %, jelikož cena se slevou nemůže klesnout pod 0,49 USD nebo ekvivalentní v dané měně či regionu.`,
  _ = `Základní cena tohoto balíku je v jedné nebo více měnách pod minimální hranicí. Z toho důvodu není možné pro tento balík nastavit slevu.`,
  _ = `Balíky označené tímto symbolem jsou přidávány ke slevě, která už probíhá. Snížené ceny tedy začnou platit ihned po uložení změn.`,
  _ = `Tato naplánovaná sleva vyústí v to, že cena tohoto balíku klesne v jedné nebo více měnách pod minimální hranici a v zemích používajících tyto měny ho nebude možné zakoupit. Abyste zajistili celosvětovou dostupnost balíku, nastavte pro něj slevu nižší než %1$s %.`,
  _ = `Základní cena tohoto balíku je v jedné nebo více měnách pod minimální hranicí. Balík tedy nebude možné zakoupit v zemích používajících tyto měny ani v zemích, kde vlivem této slevy jeho konečná cena klesne pod minimální hranici. Abyste zajistili celosvětovou dostupnost balíku, zvyšte jeho cenu alespoň na vyžadované minimum.`,
  _ = `Máte 1 neuloženou změnu. Zahozením změny dojde ke zrušení nových slev a vrácení aktualizovaných slev do jejich předchozího stavu.`,
  _ = `Máte více neuložených změn (%1$s). Zahozením změn dojde ke zrušení nových slev a vrácení aktualizovaných slev do jejich předchozího stavu.`,
  _ = `Přejít na vstupní stránku aplikace`,
