  _ = `ZLEVNIT VŠECHNY VIDITELNÉ BALÍKY`,
  _ = `Zadejte slevu v rozmezí od 10 do 95 %.`,
  _ = `Také můžete zadat „0“, čímž odeberete slevy od všech viditelných balíků.`,
  _ = `Touto akcí bude zadána sleva pro všechny viditelné balíky, a to včetně balíků s již určenými slevami, které budou přepsány. Tato akce se neliší od manuálního zadání hodnot do okýnek, jelikož nepřijdete o možnost prohlédnout si a potvrdit změny před jejich uložením.`,
  _ = `POZNÁMKA: Nejméně jeden z těchto balíků může být zlevněn maximálně o %1$s %.`,
