  _ = `Zobrazit všechny události`,
  _ = `Toto je náhled ceny, která bere v potaz zadanou procentuální slevu.`,
  _ = `BETA`,
  _ = `Zanechte zpětnou vazbu`,
  _ = `ULOŽIT PŘED POKRAČOVÁNÍM?`,
  _ = `Na této stránce se nachází nevyřízené změny, které nejsou uložené. Chcete je před opuštěním stránky uložit?`,
  _ = `Balík bez hry`,
  _ = `Tyto balíky buď zahrnují DLC nepropojená s nadřazenou aplikací, nebo jde o neherní aplikace, například filmy.`,
  _ = `Balík s více hrami`,
