  _ = `Přejít na vstupní stránku balíku`,
  _ = `Ceny tohoto balíku jsou v jedné nebo více měnách pod minimální hranicí. Posuňte tedy seznam doprava a vyhledejte konkrétní měny s upozorněním.`,
  _ = `Pro tento balík je naplánována jedna nebo více slev, které vyústí v to, že jeho cena v jedné nebo více měnách klesne pod minimální hranici. Posuňte tedy seznam doprava a vyhledejte konkrétní upozornění.`,
