  _ = `Nenašli jsme žádné balíky, které máte pod svým vydavatelem oprávnění upravovat`,
  _ = `Dokumentace`,
  _ = `Kontaktujte nás`,
  _ = `Převést ceny...`,
  _ = `Pokud chcete rychle aktualizovat ceny ve všech měnách, můžete pomocí tohoto tlačítka použít převedené ceny založené na Vámi zadané ceně v USD. Změny budete moci ještě před zveřejněním zkontrolovat.`,
  _ = `Převedení z ceny v USD`,
  _ = `Vaše ceny už odpovídají vybrané metodě převodu.`,
  _ = `Doporučené ceny`,
  _ = `Abychom Vám pomohli se správou cen napříč 35 a více podporovanými měnami, nabízí tento nástroj možnost převodu základní ceny v USD na ceny vhodné pro jednotlivé regiony. Samotný převod je založen na kombinaci hodnoty měny, kupní síly regionu, vyžadovaných daní a našich vlastních zkušeností s prodejem v tom či onom regionu.`,
  _ = `Kliknutím na tlačítko níže budou pro všechny viditelné balíky použity převedené ceny. Nebudou ovlivněny balíky skryté filtrem nebo sbalením řádek.`,
  _ = `Přečtěte si více informací o regionálních cenách.`,
  _ = `Před zveřejněním budete mít možnost prohlédnout a potvrdit změny.`,
