  _ = `Archivované sady budou viditelné pouze pro uživatele, kteří dříve odemkli nějaký z jejich achievementů.`,
  _ = `Sady pouze pro vývojáře budou viditelné pouze pro vývojáře aplikace, ať už je, nebo není vydaná.`,
