  _ = `Aplikace %1$s není vedena jako DLC pro hru %2$s.`,
  _ = `V této sadě nejsou žádné achievementy, takže se nikomu nezobrazí.`,
  _ = `Opravdu chcete odstranit tuto sadu?`,
  _ = `Odstranit`,
  _ = `Před odstraněním sady musíte přesunout nebo odstranit všechny její achievementy. Pokud chcete sadu vyřadit, ale nechcete odstranit její achievementy, můžete ji změnit na „už nedostupnou“.`,
