  _ = `Hromadné nahrání obrázků achievementů`,
  _ = `Vygenerovat z nových odemčených ikon také uzamčené`,
  _ = `Odemčený / uzamčený`,
  _ = `Vyberte achievement`,
  _ = `Pro nahrání sem přetáhněte ikony formátu PNG nebo JPG s rozměry 256×256 pixelů`,
  _ = `Když soubory pojmenujete názvem z API a přidáte „_ACHIEVED“ nebo „_UNACHIEVED“ (tzn. odemčený/uzamčený), budou obrázky automaticky přiřazeny ke stávajícím achievementům. Příklad: „LEVEL_20_ACHIEVED.png“.`,
  _ = `Záhlaví souboru formátu CSV neodpovídají očekávaným záhlavím dat nebo lokalizace`,
  _ = `Něco se pokazilo a Vaše změny nebyly uloženy. Zkuste to znovu.`,
  _ = `Je vyžadován název v API.`,
  _ = `Tento název v API už používá jiný achievement.`,
  _ = `Název nebo popis stále zahrnuje zástupný text „NEW_ACHIEVEMENT_“.`,
  _ = `Jiný achievement má v jazyce %1$s stále stejný název a popis. Každý achievement musí mít unikátní název a popis.`,
  _ = `Omezení`,
  _ = `Je použito %1$s z %2$s achievementů.`,
  _ = `Aplikace, které ještě nebyly ověřeny, jsou <1>omezeny na %1$s achievementů</1>.`,
  _ = `Je použito %1$s z %2$s sad.`,
  _ = `Bylo dosaženo maximálního počtu sad.`,
  _ = `Správa achievementů`,
  _ = `Hromadný import/export`,
  _ = `Může se někdy zobrazit s předponou „DLC“.`,
  _ = `Globální procento odemčení achievementu.`,
  _ = `Tento obrázek se nepodařilo přečíst. Zkuste ho znovu uložit a nahrát.`,
  _ = `Z tohoto obrázku nebylo možné vygenerovat uzamčenou ikonu.`,
  _ = `Zde můžete nahrát jenom jeden soubor.`,
  _ = `Hromadný import`,
  _ = `Soubory formátu CSV pro definice achievementů a lokalizaci. Pomocí tlačítek vpravo si můžete stáhnout šablony pro vyžadované soubory formátu CSV. Poznámky v závorkách v záhlaví jsou pokyny a při nahrávání jsou ignorovány.`,
  _ = `Obrázky formátu PNG pro ikony achievementů. Pojmenujte je názvy z API a přidejte k nim „_ACHIEVED“ nebo „_UNACHIEVED“. Příklad: „LEVEL_20_ACHIEVED.png“.`,
  _ = `Automaticky vygenerovat ikony pro uzamčené achievementy`,
  _ = `Povolením této možnosti dojde k automatickému vytvoření šedých „uzamčených“ ikon pro všechny zde nahrané ikony.`,
  _ = `Změny byly uloženy.`,
  _ = `Ukládání %1$s z %2$s`,
  _ = `Zastaveno na %1$s z %2$s`,
  _ = `Aktualizování sady achievementů „%1$s“`,
