  _ = `Vybrat soubory...`,
  _ = `Nahrané soubory`,
  _ = `Zde jsou uvedeny všechny soubory, které jste nahráli, a případné problémy s nimi. Odstraněním souboru dojde ke zrušení všeho, k čemu přispěl, a nevyřízené změny níže budou znovu sestaveny ze zbývajících souborů. Pro nahrazení souboru ho opravte a nahrajte znovu.`,
  _ = `Nevyřízené změny`,
  _ = `Veškeré změny níže budou použity po uložení, ale dokud tak neprovedete, nic se nezmění. Zkontrolujte tedy změny a případně opravte soubory výše.`,
  _ = `Achievementy`,
  _ = `Sady achievementů`,
  _ = `Chyby (%1$s souborů)`,
  _ = `Chyby (%1$s soubor)`,
  _ = `Chyby (%1$s souborů)`,
  _ = `Povedlo se (%1$s soubor)`,
  _ = `Povedlo se (%1$s souborů)`,
  _ = `Následující soubory vykázaly chyby. Buď je odstraňte, nebo je po opravení chyb znovu importujte.`,
  _ = `Následující soubory byly úspěšně importovány.`,
  _ = `Definice achievementů (CSV)`,
  _ = `Zde můžete definovat a upravovat achievementy své hry. Pokud zatím nejsou definovány žádné achievementy, exportováním získáte šablonu s několika řádkami „EXAMPLE_“. Ty můžete přepsat, smazat, nebo šablonu beze změny nahrát, abyste si vyzkoušeli, jak funguje importování.`,
  _ = `Již definováno: %1$s`,
  _ = `Aktuálně podporováno: %1$s`,
  _ = `Lokalizace achievementů (CSV)`,
  _ = `Upravujte názvy a popisy definovaných achievementů v jazycích nakonfigurovaných pro hru.`,
  _ = `<1>TIP: Začínáte pracovat na lokalizaci?</1> Nejprve nakonfigurujte plánované jazyky, aby soubor formátu CSV zahrnoval jejich sloupce. Poté lokalizujte achievementy a níže nahrajte vyplněný soubor.`,
  _ = `Nakonfigurovat jazyky`,
  _ = `Lokalizace sad achievementů (CSV)`,
  _ = `Upravte názvy sad achievementů v jazycích nakonfigurovaných pro hru. Samotné sady musí být nejprve vytvořeny v editoru.`,
  _ = `Export lokalizace sad (.csv)`,
  _ = `Již definováno: %1$s`,
  _ = `Ikony achievementů`,
  _ = `Aby byla ikona automaticky propojena se souvisejícím achievementem, musí používat název z API doplněný o „_ACHIEVED“ nebo „_UNACHIEVED“. Příklad: „LEVEL_20_ACHIEVED.png“.`,
