  _ = `Chyba`,
  _ = `Přidané (%1$s)`,
  _ = `Zde jsou uvedeny achievementy, které neodpovídají stávajícím názvům v API. Těmto achievementům budou přiřazena nová ID. Pokud bylo Vaším záměrem změnit názvy stávajících achievementů v API, nejprve názvy upravte v editoru.`,
  _ = `Chybějící (%1$s)`,
  _ = `Zde jsou uvedeny achievementy, které jste dříve definovali, ale nebyly nalezeny v nahraném souboru formátu CSV. Tyto achievementy zůstanou, dokud níže nezaškrtnete políčko pro jejich odstranění.`,
  _ = `Odstranit tyto achievementy`,
  _ = `Změněné (%1$s)`,
  _ = `Zde jsou uvedeny achievementy, které byly změněny. Tyto achievementy budou aktualizovány.`,
  _ = `Nezměněné (%1$s)`,
  _ = `Zde jsou uvedeny achievementy, které nebyly změněny. Tyto achievementy nebudou aktualizovány.`,
  _ = `Chybí obrázek achievementu`,
  _ = `Neplatný soubor formátu CSV. Všechny přidané achievementy musí odkazovat na statistiky v jedné sadě (nebo ve výchozí sadě).`,
  _ = `Neplatný název v API: název musí být unikátní`,
  _ = `V nahraném souboru formátu CSV byly zjištěny chyby. Opravte tedy chyby uvedené níže a soubor znovu nahrajte.`,
  _ = `Označuje změnu`,
  _ = `ID sady`,
  _ = `Zde jsou uvedeny sady, jejichž názvy byly změněny. Tyto sady budou aktualizovány.`,
  _ = `Zde jsou uvedeny nezměněné sady. Tyto sady nebudou aktualizovány.`,
  _ = `Neplatné ID sady. ID sady musí být unikátní.`,
  _ = `Neplatné ID sady. Sada s achievementy základní hry nemůže být přejmenována.`,
  _ = `Neočekávaný sloupec. „%1$s“ není podporovaný jazyk.`,
  _ = `Neplatný název. Názvy sad musí být v angličtině.`,
  _ = `Neplatný název statistiky: statistika neexistuje. Pro vytvoření nových statistik je <1>upravte</1>.`,
  _ = `Neplatné oprávnění. Achievement a statistika musí mít stejné oprávnění.`,
  _ = `Neplatné celé číslo. Když je statistika nastavena na celé číslo (integer), hodnota musí být také celé číslo.`,
  _ = `Neplatný rozsah postupu. Maximum musí být větší než minimum.`,
