  _ = `Neplatné ID sady. ID sady neexistuje.`,
  _ = `Změnit pořadí sad`,
  _ = `Přetažením sad achievementů určíte pořadí zobrazení pro uživatele.`,
  _ = `Výchozí sadu nelze přesunout.`,
  _ = `Možnosti`,
  _ = `Obrázek musí mít stejnou výšku a šířku.`,
  _ = `Rozměry obrázku musí být alespoň %1$s×%1$s pixelů.`,
  _ = `Neznámý typ obsahu`,
  _ = `Nebyl nalezen žádný achievement, který má v API název „%1$s“, a tudíž nelze přiřadit obrázek.`,
  _ = `V nahraném souboru definic chybí achievement „%1$s“, takže tato ikona nebude přiřazena. Buď achievement přidejte do souboru formátu CSV, nebo soubor odeberte a ikony nahrajte samostatně.`,
  _ = `Tento achievement chybí v nahraném souboru definic, takže jeho lokalizace nebude aktualizována. Buď achievement přidejte do souboru formátu CSV, nebo ze souboru odstraňte jeho lokalizační řetězce.`,
  _ = `Nebyl nalezen žádný achievement, který má v API tento název, a tudíž nebude aktualizována jeho lokalizace. Názvy v API rozlišují velká a malá písmena.`,
  _ = `Některé změny nebyly uloženy. Chcete je zahodit?`,
  _ = `Neplatné maximum postupu. Maximum postupu achievementu musí být menší nebo rovno maximu statistiky.`,
  _ = `Jazyky achievementů`,
  _ = `Vyberte jazyky, které Vaše achievementy podporují. Tím bude povolena lokalizace achievementů do těchto jazyků v editoru a také jejich hromadné exportování/importování. Když vyžádáte achievementy skrze API, služba Steam Vám vrátí lokalizovaný text.`,
  _ = `Uložit importovaná data`,
  _ = `NOVÉ`,
